let state={configured:false,authenticated:false,writeReady:false},loginPromise;
const base='/lan-api';
async function request(path,body){const r=await fetch(base+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.error?.message||'操作连接失败');return data;}
export function operatorEnabled(){return state.authenticated&&state.writeReady;}
export async function refreshOperator(){state=await request('/operator/status');render();return state;}
function render(){const button=document.getElementById('operator-login'),logout=document.getElementById('operator-logout');if(button){button.textContent=state.authenticated?'操作已登录':'操作登录';button.classList.toggle('authenticated',state.authenticated);button.title=state.authenticated?'保持登录，可继续操作；每次提交前核对变更':'输入操作密码后可编辑计划';}if(logout)logout.hidden=!state.authenticated;}
export function initializeOperator(notify){document.getElementById('operator-login').onclick=()=>void ensureOperator().catch(e=>notify(e.message));document.getElementById('operator-logout').onclick=async()=>{try{await request('/operator/logout',{});await refreshOperator();notify('已退出操作登录，仍可查看数据');}catch(e){notify(e.message);}};void refreshOperator().catch(()=>{});}
export async function ensureOperator(){
 await refreshOperator();
 if(!state.configured){notice('尚未设置操作密码','请在采集电脑打开 http://127.0.0.1:5173/connect.html，设置独立的操作密码。设置后，内网用户可在此登录。');return false;}
 if(!state.authenticated){if(!loginPromise)loginPromise=login().finally(()=>loginPromise=null);if(!await loginPromise)return false;await refreshOperator();}
 if(!state.writeReady){notice('操作连接待更新','操作登录已保留。请在采集电脑的 Chrome 扩展管理页重新加载“千川商品本机连接”（1.3.0），并保持目标账户商品页打开。更新完成后可继续操作。');return false;}
 return true;
}
function notice(title,text){const d=document.createElement('dialog');d.className='operation-dialog';d.innerHTML='<header><h2></h2></header><p></p><footer><button type="button">知道了</button></footer>';d.querySelector('h2').textContent=title;d.querySelector('p').textContent=text;document.body.append(d);d.showModal();d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();}
function login(){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='operation-dialog operator-dialog';d.setAttribute('aria-label','操作密码登录');d.innerHTML='<form><header><h2>操作登录</h2><button type="button" data-cancel aria-label="关闭登录">×</button></header><p>账户 1000000000000000 · 登录后可编辑预算、ROI、投放状态及调控任务。</p><label>操作密码<input type="password" name="password" autocomplete="current-password" required maxlength="128" autofocus></label><small>保持登录30天，使用时续期；可随时退出。请使用此网页的操作密码。</small><p class="operation-error" role="alert"></p><footer><button type="button" data-cancel>取消</button><button class="primary" type="submit">登录并继续</button></footer></form>';document.body.append(d);d.showModal();let success=false,working=false;d.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{if(!working)d.close();});d.querySelector('form').onsubmit=async e=>{e.preventDefault();if(working)return;working=true;const b=d.querySelector('[type=submit]');b.disabled=true;try{await request('/operator/login',{password:d.querySelector('input').value});d.querySelector('input').value='';success=true;d.close();}catch(error){d.querySelector('.operation-error').textContent=error.message;}finally{working=false;b.disabled=false;}};d.oncancel=e=>{if(working)e.preventDefault();};d.onclose=()=>{d.remove();resolve(success);};});}
